commands.command:
set -eu
git fetch origin work/ux-evolution
test "$(git rev-parse HEAD)" = "$(git rev-parse origin/work/ux-evolution)"
test -z "$(git status --porcelain)"
python3 - <<'PY'
from pathlib import Path
p=Path('apps/mobile/src/features/plugs/components/PlugDeleteConfirmModal.tsx')
s=p.read_text()
assert s.count("import { Modal } from '@lcl/ui';")==1
s=s.replace("import { Modal } from '@lcl/ui';","import { IonButton } from '@ionic/react';\nimport { Modal } from '@lcl/ui';")
old='''        <button
          className="secondary-action secondary-action--danger"
          type="button"
          title={t('hardware.shelly.deleteTitle')}
          onClick={onConfirm}
        >
          {t('common.delete')}
        </button>'''
new='''        <IonButton
          className="plug-settings-ionic-action plug-settings-ionic-action--secondary plug-settings-ionic-action--danger"
          fill="outline"
          type="button"
          title={t('hardware.shelly.deleteTitle')}
          onClick={onConfirm}
        >
          {t('common.delete')}
        </IonButton>'''
assert s.count(old)==1
p.write_text(s.replace(old,new))
p=Path('apps/mobile/src/features/plugs/components/PlugSettingsSurface.css')
s=p.read_text()
anchor='''.plug-settings-ionic-action--secondary {
  --background: var(--lcl-color-surface);
  --border-color: var(--lcl-color-border);
  --border-style: solid;
  --border-width: var(--lcl-border-width-sm);
  --color: var(--lcl-color-text);
}'''
assert s.count(anchor)==1
s=s.replace(anchor,anchor+'''

.plug-settings-ionic-action--danger {
  --border-color: var(--lcl-color-status-danger-border);
  --color: var(--lcl-color-status-danger-text);
}''')
p.write_text(s)
p=Path('apps/mobile/src/features/plugs/components/PlugDeleteConfirmModal.test.tsx')
assert not p.exists()
p.write_text('''import { I18nProvider, setLocalePreference } from '../../../app/i18n.js';
import { getIonicButton } from '../../../test/ionicTestEvents.js';
import { cleanup, fireEvent, render, screen, within } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { PlugDeleteConfirmModal } from './PlugDeleteConfirmModal.js';

describe('PlugDeleteConfirmModal destructive action guard', () => {
  beforeEach(() => setLocalePreference('pl'));
  afterEach(() => cleanup());

  it('does not delete on open or cancel and calls confirm exactly once on Ionic click', () => {
    const onClose = vi.fn();
    const onConfirm = vi.fn();
    const { rerender } = render(
      <I18nProvider>
        <PlugDeleteConfirmModal deviceName="Salon" onClose={onClose} onConfirm={onConfirm} />
      </I18nProvider>
    );
    const dialog = screen.getByRole('dialog', { name: 'Usunąć gniazdko?' });
    expect(dialog).toHaveTextContent('Salon');
    expect(onConfirm).not.toHaveBeenCalled();
    const confirm = getIonicButton(dialog, 'Usuń');
    expect(confirm).toHaveClass('plug-settings-ionic-action--danger');
    expect(confirm).toHaveAttribute('title');
    fireEvent.click(within(dialog).getByRole('button', { name: 'Anuluj' }));
    expect(onClose).toHaveBeenCalledOnce();
    expect(onConfirm).not.toHaveBeenCalled();
    fireEvent.click(confirm);
    expect(onConfirm).toHaveBeenCalledOnce();
    rerender(
      <I18nProvider>
        <PlugDeleteConfirmModal deviceName={null} onClose={onClose} onConfirm={onConfirm} />
      </I18nProvider>
    );
    expect(screen.queryByRole('dialog')).toBeNull();
    expect(onConfirm).toHaveBeenCalledOnce();
  });
});
''')
PY
pnpm exec prettier --write apps/mobile/src/features/plugs/components/PlugDeleteConfirmModal.tsx apps/mobile/src/features/plugs/components/PlugDeleteConfirmModal.test.tsx apps/mobile/src/features/plugs/components/PlugSettingsSurface.css
pnpm --filter @lcl/mobile exec vitest run src/features/plugs/components/PlugDeleteConfirmModal.test.tsx src/__tests__/modal.test.tsx --reporter=default
pnpm --filter @lcl/mobile typecheck
git diff --check
git add apps/mobile/src/features/plugs/components/PlugDeleteConfirmModal.tsx apps/mobile/src/features/plugs/components/PlugDeleteConfirmModal.test.tsx apps/mobile/src/features/plugs/components/PlugSettingsSurface.css
git commit -m "refactor(ionic): migrate guarded Plug deletion confirm button"
git push origin HEAD:refs/heads/work/ux-evolution
echo "MIGRATION_COMMIT=$(git rev-parse HEAD)"
git status --short
